function d_dimcheck(P,R){var terms=P.terms||[];var base=terms.length?terms[0].dims:null;var bad=terms.filter(function(t){return JSON.stringify(t.dims)!==JSON.stringify(base);});return{terms:terms.length,consistent:bad.length===0,offenders:bad.map(function(t){return t.name;})};}

